{
  "requirement_id": "SFMC-REQ-030",
  "raw_text": "The SFMC shall immediately notify the pilot of all critical faults.",
  "software_requirement_status": "YES",
  "quality_status": "NEEDS_REVIEW",
  "quality_issues": [
    {
      "issue_code": "UNDEFINED_TERM",
      "severity": "MAJOR",
      "explanation": "The term 'critical faults' is used in the requirement but is not defined anywhere in the SRS. The SRS explicitly lists 'Definition of a critical fault' as an open item (Section 11, item 3), indicating that this key term is currently undefined. This lack of definition impairs clarity and verifiability of the requirement.",
      "srs_evidence": [
        {
          "locator": "11. Open Items",
          "excerpt": "3. Definition of a **critical fault**."
        },
        {
          "locator": "3.6 Vehicle Health Monitoring",
          "excerpt": "SFMC-REQ-030 — Critical Faults\nThe SFMC shall immediately notify the pilot of all critical faults."
        }
      ],
      "nasa_references": [
        {
          "document": "NASA-HDBK-2203-5.09",
          "authority": "HANDBOOK_GUIDANCE",
          "section": "§3.2.1.9",
          "swe_id": null,
          "url": "https://swehb.nasa.gov/spaces/SWEHBVD/pages/102695669/5.09+-+SRS+-+Software+Requirements+Specification"
        }
      ],
      "recommendation": "Define 'critical fault' explicitly in the SRS to remove ambiguity and enable verification. This definition should include criteria for fault severity and examples if possible.",
      "requires_stakeholder_input": true
    }
  ],
  "primary_swe_id": null,
  "primary_swe_strength": null,
  "swe_links": [],
  "summary": "The requirement mandates immediate pilot notification of all critical faults, which is essential for fault management and safety. However, the key term 'critical faults' is undefined in the SRS, limiting clarity and verifiability. The requirement is otherwise consistent with fault management guidance but needs definition of critical faults to be fully acceptable."
}
